# Keep related equalities on separate lines at mobile widths; never change owner text.
def display_rows(text):
 def replace(match):
  value=match[1]
  if r'\quad' not in value:return match[0]
  return r'\[\begin{gathered}'+r'\\'.join(x.strip().strip(',').strip() for x in value.split(r'\quad'))+r'\end{gathered}\]'
 return re.sub(r'\\\[(.*?)\\\]',replace,text,flags=re.S)
for lesson in lessons:
 for key in ['before','ideas','method']:lesson[key]=display_rows(lesson[key])
 for example in lesson['examples']:
  for key in ['question','solution']:example[key]=display_rows(example[key])
def digest(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def tex(v):return s.latex(s.sympify(v))
def f(key,label,value):return dict(key=key,label=label,type='number',expected=str(value))
