 q=dict(id=uid,family_uid=f'M4U-9231-INF-{code}{family}',lesson=key,title=title,collection='short' if v==1 else 'variant',prompt_html=prompt,answer_html=answer,solution_html=solution,hint_html='<p>Identify the sampling design, parameter and tail before calculating. Keep all requested quantities, use the stated critical value and round only when instructed.</p>',marks=len(fields),difficulty=2 if family<3 else 3,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='A1',marks=1,description_html='<p>Give the correct '+html.escape(z['label'].lower())+'.</p>') for z in fields])],verification=uid)
