for v,(n,total,ss,offset) in enumerate([(9,72,596,0),(10,12,s.Rational(234,5),30)],1):
 mean=s.Rational(total,n)+offset;var=(ss-s.Rational(total*total,n))/(n-1);se=s.sqrt(var/n)
 add('one_sample','S',1,v,'Mean, variance and standard error',r'<p>A random sample has \(n='+str(n)+r'\), \(\sum u='+str(total)+r'\), \(\sum u^2='+tex(ss)+r'\), where \(x=u+'+str(offset)+r'\). Find the mean of x, its unbiased variance and the estimated standard error of its mean, exactly.</p>',[f('mean','Sample mean',mean),f('variance','Unbiased variance',var),f('se','Standard error',se)],r'<p>Use the coded mean plus the offset. Calculate \(s^2=[\sum u^2-(\sum u)^2/n]/(n-1)\) and then \(s/\sqrt n\). Adding a constant leaves the variance unchanged.</p>',dict(kind='summary',n=n,total=str(total),squares=str(ss),offset=str(offset),expected=list(map(str,[mean,var,se]))))
